package solution

import (
	"errors"
	"reflect"
	"testing"
)

func TestInventoryLifecycleOrderingAndClear(t *testing.T) {
	inventory := NewInventory()
	if inventory == nil {
		t.Fatal("NewInventory returned nil")
	}
	if got := inventory.IDs(); got == nil || len(got) != 0 {
		t.Fatalf("empty IDs() = %#v, want non-nil empty slice", got)
	}
	if got := inventory.Snapshot(); got == nil || len(got) != 0 {
		t.Fatalf("empty Snapshot() = %#v, want non-nil empty map", got)
	}

	assets := []Asset{
		{ID: "20", Name: "Router", Zone: "west", Tags: []string{"network"}},
		{ID: "100", Name: "Sensor", Zone: "east", Tags: []string{}},
		{ID: "3", Name: "Switch", Zone: "north", Tags: nil},
	}
	for _, asset := range assets {
		if err := inventory.Add(asset); err != nil {
			t.Fatalf("Add(%#v) returned %v", asset, err)
		}
	}
	if got, want := inventory.IDs(), []string{"100", "20", "3"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("IDs() = %#v, want %#v", got, want)
	}

	updated := Asset{ID: "20", Name: "Core Router", Zone: "central", Tags: []string{"core", "network"}}
	if err := inventory.Update(updated); err != nil {
		t.Fatalf("Update returned %v", err)
	}
	if got, err := inventory.Get("20"); err != nil || !reflect.DeepEqual(got, updated) {
		t.Fatalf("Get after Update = (%#v, %v), want (%#v, nil)", got, err, updated)
	}
	if err := inventory.Delete("3"); err != nil {
		t.Fatalf("Delete existing returned %v", err)
	}
	if _, err := inventory.Get("3"); !errors.Is(err, ErrAssetNotFound) {
		t.Fatalf("Get deleted error = %v, want ErrAssetNotFound", err)
	}

	inventory.Clear()
	if got := inventory.IDs(); got == nil || len(got) != 0 {
		t.Fatalf("IDs after Clear = %#v", got)
	}
	if got := inventory.Snapshot(); got == nil || len(got) != 0 {
		t.Fatalf("Snapshot after Clear = %#v", got)
	}
}

func TestInventoryValidationAndErrors(t *testing.T) {
	invalid := []Asset{
		{ID: "", Name: "N", Zone: "Z"},
		{ID: "0", Name: "N", Zone: "Z"},
		{ID: "00", Name: "N", Zone: "Z"},
		{ID: "01", Name: "N", Zone: "Z"},
		{ID: "+1", Name: "N", Zone: "Z"},
		{ID: "-1", Name: "N", Zone: "Z"},
		{ID: "1.0", Name: "N", Zone: "Z"},
		{ID: "1A", Name: "N", Zone: "Z"},
		{ID: "1", Name: "", Zone: "Z"},
		{ID: "1", Name: "N", Zone: ""},
		{ID: "1", Name: "N", Zone: "Z", Tags: []string{"ok", ""}},
	}
	for _, asset := range invalid {
		inventory := NewInventory()
		if err := inventory.Add(asset); !errors.Is(err, ErrInvalidAsset) {
			t.Errorf("Add(%#v) error = %v, want ErrInvalidAsset", asset, err)
		}
		if got := inventory.IDs(); got == nil || len(got) != 0 {
			t.Errorf("invalid Add changed inventory: %#v", got)
		}
	}

	inventory := NewInventory()
	original := Asset{ID: "1", Name: "Original", Zone: "A", Tags: []string{"tag"}}
	if err := inventory.Add(original); err != nil {
		t.Fatal(err)
	}
	if err := inventory.Add(Asset{ID: "1", Name: "Duplicate", Zone: "B"}); !errors.Is(err, ErrAssetExists) {
		t.Errorf("duplicate Add error = %v, want ErrAssetExists", err)
	}
	invalidUpdate := Asset{ID: "1", Name: "", Zone: "A"}
	if err := inventory.Update(invalidUpdate); !errors.Is(err, ErrInvalidAsset) {
		t.Errorf("invalid Update error = %v, want ErrInvalidAsset", err)
	}
	if got, _ := inventory.Get("1"); !reflect.DeepEqual(got, original) {
		t.Errorf("rejected operation changed original: %#v", got)
	}

	unknown := Asset{ID: "2", Name: "Unknown", Zone: "B"}
	if err := inventory.Update(unknown); !errors.Is(err, ErrAssetNotFound) {
		t.Errorf("Update unknown error = %v, want ErrAssetNotFound", err)
	}
	if err := inventory.Delete("2"); !errors.Is(err, ErrAssetNotFound) {
		t.Errorf("Delete unknown error = %v, want ErrAssetNotFound", err)
	}
	if _, err := inventory.Get("2"); !errors.Is(err, ErrAssetNotFound) {
		t.Errorf("Get unknown error = %v, want ErrAssetNotFound", err)
	}
}

func TestInventoryCopiesTagsOnAllBoundaries(t *testing.T) {
	inventory := NewInventory()
	input := Asset{ID: "7", Name: "Asset", Zone: "Zone", Tags: []string{"red", "blue"}}
	if err := inventory.Add(input); err != nil {
		t.Fatal(err)
	}
	input.Tags[0] = "changed-input"
	got, _ := inventory.Get("7")
	if !reflect.DeepEqual(got.Tags, []string{"red", "blue"}) {
		t.Fatalf("Add retained caller tag slice: %#v", got.Tags)
	}

	got.Tags[0] = "changed-get"
	again, _ := inventory.Get("7")
	if !reflect.DeepEqual(again.Tags, []string{"red", "blue"}) {
		t.Fatalf("Get returned aliased tags: %#v", again.Tags)
	}

	snapshot := inventory.Snapshot()
	asset := snapshot["7"]
	asset.Tags[1] = "changed-snapshot"
	asset.Name = "changed"
	snapshot["7"] = asset
	delete(snapshot, "7")
	again, _ = inventory.Get("7")
	if again.Name != "Asset" || !reflect.DeepEqual(again.Tags, []string{"red", "blue"}) {
		t.Fatalf("Snapshot exposed inventory state: %#v", again)
	}

	replacement := Asset{ID: "7", Name: "Updated", Zone: "Zone", Tags: []string{"new"}}
	if err := inventory.Update(replacement); err != nil {
		t.Fatal(err)
	}
	replacement.Tags[0] = "changed-update-input"
	again, _ = inventory.Get("7")
	if !reflect.DeepEqual(again.Tags, []string{"new"}) {
		t.Fatalf("Update retained caller tag slice: %#v", again.Tags)
	}
}

